INSERT INTO assets (owner_id,title,form,genre,episodes,ep_minutes,total_minutes,stage,logline,synopsis,team,ai_tools,rights_status,public_consent,cover) VALUES (1,'霓虹渡口','AI剧集','都市悬疑',12,8,96,'已成片','一名摆渡人在雨夜港口发现每一位乘客都来自同一场未发生的事故。','港城最后一班渡轮的摆渡人阿渡，在连续十二个雨夜里遇见同一批乘客……（演示数据）','林深（导演/编剧）、何川（AIGC美术）、宋雨（剪辑）','视频生成模型+人工精修；配音为授权真人','已清权',1,'noir');
INSERT INTO assets (owner_id,title,form,genre,episodes,ep_minutes,total_minutes,stage,logline,synopsis,team,ai_tools,rights_status,public_consent,cover) VALUES (1,'山海食肆','AI漫剧','东方奇幻·美食',30,3,90,'开发中','山海经异兽开在人间的一家深夜食堂。','以《山海经》为灵感，每集一只异兽、一道菜、一段人间故事。（演示数据）','林深、苏芮','图像生成+分镜+视频生成','已清权',1,'myth');
INSERT INTO assets (owner_id,title,form,genre,episodes,ep_minutes,total_minutes,stage,logline,synopsis,team,ai_tools,rights_status,public_consent,cover) VALUES (2,'星环邮差','AIGC电影','科幻·亲情',1,72,72,'制作中','近未来，一位老邮差用最后一枚纸质邮票寄出给火星女儿的信。','（演示数据）跨越两颗星球的家书，探讨数字时代的情感连接。','苏芮（制片）、王野（导演）','全链路AIGC工作流','已清权',1,'scifi');
INSERT INTO assets (owner_id,title,form,genre,episodes,ep_minutes,total_minutes,stage,logline,synopsis,team,ai_tools,rights_status,public_consent,cover) VALUES (2,'长安夜行录','微短剧','古装·悬疑',60,2,120,'试制中','大唐不良人追查一桩只在月圆之夜发生的连环案。','（演示数据）竖屏微短剧，强钩子、快节奏。','苏芮团队','AI角色一致性+实拍合成','待清权',0,'tang');
